  nextId=nextId+1;seen[v]=nextId
  local keys={};for k in pairs(v)do keys[#keys+1]=k end
  table.sort(keys,function(a,b)if type(a)==type(b)then return a<b else return type(a)<type(b)end end)
  local out={'#'..nextId..'{'}
  for _,k in ipairs(keys)do out[#out+1]=visit(k)..'='..visit(v[k])..';'end
